use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use chrono::{Datelike, Duration};
use std::collections::BTreeMap;
use std::io::{self, Write};

const BILLING_UNIT_SECONDS: i64 = 15 * 60;

pub struct BillWeeklyCommand;

fn billed_seconds(entry: &TimeEntry) -> i64 {
    let duration = entry.duration.max(0);
    ((duration + BILLING_UNIT_SECONDS - 1) / BILLING_UNIT_SECONDS) * BILLING_UNIT_SECONDS
}

fn weekly_totals(entries: impl IntoIterator<Item = TimeEntry>) -> BTreeMap<chrono::NaiveDate, i64> {
    let mut totals = BTreeMap::new();
    for entry in entries {
        if !entry.billable || entry.stop.is_none() {
            continue;
        }

        let start_date = entry.start.date_naive();
        let monday = start_date - Duration::days(start_date.weekday().num_days_from_monday() as i64);
        *totals.entry(monday).or_insert(0) += billed_seconds(&entry);
    }
    totals
}

fn write_totals(mut output: impl Write, totals: &BTreeMap<chrono::NaiveDate, i64>) {
    if totals.is_empty() {
        writeln!(output, "(no data)").expect("failed to print");
        return;
    }

    let total: i64 = totals.values().sum();
    for (week, seconds) in totals {
        writeln!(output, "{}  {seconds}s", week.format("%Y-%m-%d")).expect("failed to print");
    }
    writeln!(output, "Total  {total}s").expect("failed to print");
}

impl BillWeeklyCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client
            .get_time_entries_filtered_minimal(since, until)
            .await?;
        let totals = weekly_totals(entries);

        write_totals(io::stdout(), &totals);
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use chrono::{TimeZone, Utc};

    fn entry(start: &str, duration: i64, billable: bool, stopped: bool) -> TimeEntry {
        TimeEntry {
            id: 1,
            description: String::new(),
            start: Utc.datetime_from_str(start, "%Y-%m-%dT%H:%M:%SZ").unwrap(),
            stop: stopped.then_some(Utc.timestamp_opt(0, 0).single().unwrap()),
            duration,
            billable,
            workspace_id: 1,
            tags: vec![],
            project: None,
            task: None,
            created_with: None,
        }
    }

    #[test]
    fn weekly_totals_rounds_each_entry_and_uses_utc_iso_monday() {
        let totals = weekly_totals([
            entry("2026-01-04T23:30:00Z", 1, true, true),
            entry("2026-01-05T00:30:00Z", 901, true, true),
        ]);

        assert_eq!(totals.get(&chrono::NaiveDate::from_ymd_opt(2025, 12, 29)), Some(&900));
        assert_eq!(totals.get(&chrono::NaiveDate::from_ymd_opt(2026, 1, 5)), Some(&1800));
    }

    #[test]
    fn weekly_totals_excludes_non_billable_and_running_entries() {
        let totals = weekly_totals([
            entry("2026-01-05T00:00:00Z", 900, false, true),
            entry("2026-01-05T01:00:00Z", 900, true, false),
        ]);

        assert!(totals.is_empty());
    }

    #[test]
    fn write_totals_prints_empty_window() {
        let mut output = Vec::new();
        write_totals(&mut output, &BTreeMap::new());
        assert_eq!(String::from_utf8(output).unwrap(), "(no data)\n");
    }
}

