use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use chrono::{Datelike, Duration};
use serde::Serialize;
use std::collections::BTreeMap;
use std::io::{self, Write};

const BILLING_UNIT_SECONDS: i64 = 15 * 60;

pub struct BillWeeklyCommand;

#[derive(Serialize)]
struct WeeklyBillingWeek {
    week: String,
    billable_seconds: i64,
}

#[derive(Serialize)]
struct WeeklyBillingOutput {
    weeks: Vec<WeeklyBillingWeek>,
    total_billable_seconds: i64,
}

fn billed_seconds(entry: &TimeEntry) -> i64 {
    let duration = entry.duration.max(0);
    ((duration + BILLING_UNIT_SECONDS - 1) / BILLING_UNIT_SECONDS) * BILLING_UNIT_SECONDS
}

fn weekly_totals(entries: impl IntoIterator<Item = TimeEntry>) -> BTreeMap<chrono::NaiveDate, i64> {
    let mut totals = BTreeMap::new();
    for entry in entries {
        if !entry.billable || entry.stop.is_none() {
            continue;
        }

        let start_date = entry.start.date_naive();
        let monday =
            start_date - Duration::days(start_date.weekday().num_days_from_monday() as i64);
        *totals.entry(monday).or_insert(0) += billed_seconds(&entry);
    }
    totals
}

fn write_totals(
    mut output: impl Write,
    totals: &BTreeMap<chrono::NaiveDate, i64>,
    json: bool,
) {
    if json {
        let total_billable_seconds = totals.values().sum();
        let result = WeeklyBillingOutput {
            weeks: totals
                .iter()
                .map(|(week, seconds)| WeeklyBillingWeek {
                    week: week.format("%Y-%m-%d").to_string(),
                    billable_seconds: *seconds,
                })
                .collect(),
            total_billable_seconds,
        };
        writeln!(
            output,
            "{}",
            serde_json::to_string(&result).expect("failed to serialize billing totals")
        )
        .expect("failed to print");
        return;
    }

    if totals.is_empty() {
        writeln!(output, "(no data)").expect("failed to print");
        return;
    }

    let total: i64 = totals.values().sum();
    for (week, seconds) in totals {
        writeln!(output, "{}  {seconds}s", week.format("%Y-%m-%d")).expect("failed to print");
    }
    writeln!(output, "Total  {total}s").expect("failed to print");
}

impl BillWeeklyCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
        json: bool,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client
            .get_time_entries_filtered_minimal(since, until)
            .await?;
        let totals = weekly_totals(entries);

        write_totals(io::stdout(), &totals, json);
        Ok(())
    }
}

